import { useQuery } from '@tanstack/react-query'
import { api } from '@/lib/api'
import { Brain, Play, Zap } from 'lucide-react'
import { useState } from 'react'

export function MetaSkills() {
  const { data: metaskills } = useQuery({ queryKey: ['metaskills'], queryFn: api.getMetaSkills })
  const [running, setRunning] = useState<string | null>(null)
  const [result, setResult] = useState<Record<string, unknown>>({})

  const handleRun = async (name: string) => {
    setRunning(name)
    try {
      const res = await api.runMetaSkill(name, {})
      setResult((prev) => ({ ...prev, [name]: res }))
    } catch (e) {
      setResult((prev) => ({ ...prev, [name]: { error: (e as Error).message } }))
    } finally {
      setRunning(null)
    }
  }

  return (
    <div className="p-6 space-y-6">
      <div>
        <h2 className="text-2xl font-bold">元技能</h2>
        <p className="text-muted-foreground">内置原子操作能力（无需 LLM 即可执行）</p>
      </div>

      <div className="grid gap-3 sm:grid-cols-2">
        {!metaskills ? null : metaskills.map((ms) => (
          <div key={ms.name} className="rounded-xl border bg-card p-4">
            <div className="flex items-start gap-3">
              <Brain className="h-5 w-5 text-purple-500 mt-0.5" />
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <h3 className="font-medium text-sm">{ms.name}</h3>
                  {ms.zero_llm && (
                    <span className="flex items-center gap-1 rounded bg-green-500/10 px-1.5 py-0.5 text-xs text-green-600">
                      <Zap className="h-3 w-3" /> 免LLM
                    </span>
                  )}
                </div>
                <p className="mt-1 text-xs text-muted-foreground">{ms.description}</p>
                <div className="mt-2 flex gap-2 flex-wrap">
                  {Object.entries(ms.inputs).map(([k, v]) => (
                    <span key={k} className="rounded bg-blue-500/10 px-1.5 py-0.5 text-xs text-blue-600">
                      {k}: {v}
                    </span>
                  ))}
                </div>
                <button
                  onClick={() => handleRun(ms.name)}
                  disabled={running === ms.name}
                  className="mt-3 flex items-center gap-1 rounded-lg bg-secondary px-3 py-1.5 text-xs hover:bg-secondary/80 disabled:opacity-50"
                >
                  <Play className="h-3 w-3" /> {running === ms.name ? '执行中...' : '测试运行'}
                </button>
                {result[ms.name] != null && (
                  <pre className="mt-2 rounded bg-muted p-2 text-xs overflow-auto max-h-32">
                    {JSON.stringify(result[ms.name], null, 2)}
                  </pre>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
